<?php require 'config.php';need('seller');$st=myStore($pdo);$sid=$st['id'];$t=$_GET['t']??'resumen';
if($_SERVER['REQUEST_METHOD']==='POST'){chk();
 if(isset($_POST['store'])){$pdo->prepare('UPDATE stores SET name=?,region=?,description=? WHERE id=?')->execute([trim($_POST['name']),$_POST['region'],trim($_POST['description']),$sid]);flash('Tienda actualizada.');header('Location: panel.php?t=tienda');exit;}
 if(isset($_POST['newp'])){$f=null;
  if(!empty($_FILES['image']['name'])&&$_FILES['image']['error']===0){$ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION));
   if(in_array($ext,['jpg','jpeg','png','webp'])&&$_FILES['image']['size']<3e6&&getimagesize($_FILES['image']['tmp_name'])){$f=bin2hex(random_bytes(8)).".$ext";move_uploaded_file($_FILES['image']['tmp_name'],"uploads/$f");}
   else{flash('La foto debe ser JPG, PNG o WEBP de menos de 3 MB.');header('Location: panel.php?t=productos');exit;}}
  $pdo->prepare('INSERT INTO products(store_id,category_id,name,description,price,stock,image) VALUES(?,?,?,?,?,?,?)')->execute([$sid,(int)$_POST['cat'],trim($_POST['name']),trim($_POST['description']),max(0,(float)$_POST['price']),max(0,(int)$_POST['stock']),$f]);flash('Producto publicado.');header('Location: panel.php?t=productos');exit;}
 if(isset($_POST['delp'])){$pdo->prepare('DELETE FROM products WHERE id=? AND store_id=?')->execute([(int)$_POST['delp'],$sid]);flash('Producto eliminado.');header('Location: panel.php?t=productos');exit;}
 if(isset($_POST['status'])){$pdo->prepare('UPDATE order_items SET status=? WHERE id=? AND store_id=?')->execute([in_array($_POST['status'],['pendiente','enviado','entregado'])?$_POST['status']:'pendiente',(int)$_POST['item'],$sid]);header('Location: panel.php?t=pedidos');exit;}}
$title='Panel del vendedor';include 'app/Views/layout/header.php';
echo '<h1>'.e($st['name']).'</h1><div class="tabs">';foreach(['resumen'=>'Métricas','productos'=>'Productos','pedidos'=>'Pedidos','tienda'=>'Mi tienda'] as $k=>$v)echo '<a class="'.($t===$k?'on':'').'" href="panel.php?t='.$k.'">'.$v.'</a>';echo '</div>';
if($t==='resumen'){$m=$pdo->prepare('SELECT COALESCE(SUM(qty*price),0) tot,COUNT(DISTINCT order_id) ped,COALESCE(SUM(qty),0) uni FROM order_items WHERE store_id=?');$m->execute([$sid]);$m=$m->fetch();
 $pend=$pdo->prepare("SELECT COUNT(*) FROM order_items WHERE store_id=? AND status='pendiente'");$pend->execute([$sid]);
 $top=$pdo->prepare('SELECT p.name,SUM(oi.qty) u,SUM(oi.qty*oi.price) m FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.store_id=? GROUP BY p.id ORDER BY u DESC LIMIT 5');$top->execute([$sid]);
 $dia=$pdo->prepare('SELECT DATE(o.created_at) d,SUM(oi.qty*oi.price) m FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.store_id=? AND o.created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY d ORDER BY d');$dia->execute([$sid]);$dia=$dia->fetchAll();$mx=max(1,...array_column($dia,'m')?:[1]);?>
<div class="stats"><div><b><?=money($m['tot'])?></b>Ventas totales</div><div><b><?=$m['ped']?></b>Pedidos</div><div><b><?=$m['uni']?></b>Unidades vendidas</div><div><b><?=$pend->fetchColumn()?></b>Por enviar</div></div>
<h2>Ventas de los últimos 7 días</h2><div class="bars"><?php foreach($dia as $d):?><div><i style="height:<?=round($d['m']/$mx*100)?>%"></i><small><?=substr($d['d'],5)?><br><?=money($d['m'])?></small></div><?php endforeach;if(!$dia)echo '<p class="muted">Todavía no hay ventas esta semana.</p>';?></div>
<h2>Más vendidos</h2><table><?php foreach($top as $x):?><tr><td><?=e($x['name'])?></td><td><?=$x['u']?> uds</td><td><?=money($x['m'])?></td></tr><?php endforeach;?></table>
<?php }elseif($t==='productos'){$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$ps=$pdo->prepare('SELECT * FROM products WHERE store_id=? ORDER BY id DESC');$ps->execute([$sid]);?>
<form method="post" enctype="multipart/form-data" class="card"><input type="hidden" name="t" value="<?=csrf()?>"><h3>Publicar producto</h3><label>Nombre<input name="name" required></label><label>Descripción<textarea name="description" required></textarea></label><label>Categoría<select name="cat"><?php foreach($cats as $c)echo '<option value="'.$c['id'].'">'.e($c['name']).'</option>';?></select></label><label>Precio (S/)<input type="number" step="0.01" name="price" required></label><label>Stock<input type="number" name="stock" value="1" min="0"></label><label>Foto<input type="file" name="image" accept="image/*"></label><button name="newp" class="btn">Publicar producto</button></form>
<table><?php foreach($ps as $p):?><tr><td><?=e($p['name'])?></td><td><?=money($p['price'])?></td><td>Stock <?=$p['stock']?></td><td><form method="post"><input type="hidden" name="t" value="<?=csrf()?>"><button name="delp" value="<?=$p['id']?>" class="link" onclick="return confirm('¿Eliminar este producto?')">Eliminar</button></form></td></tr><?php endforeach;?></table>
<?php }elseif($t==='pedidos'){$o=$pdo->prepare('SELECT oi.id,oi.qty,oi.price,oi.status,o.id oid,o.address,u.name buyer,p.name FROM order_items oi JOIN orders o ON o.id=oi.order_id JOIN users u ON u.id=o.user_id JOIN products p ON p.id=oi.product_id WHERE oi.store_id=? ORDER BY o.id DESC');$o->execute([$sid]);$o=$o->fetchAll();if(!$o)echo '<p class="muted">Aún no tienes pedidos.</p>';?>
<table><?php foreach($o as $x):?><tr><td>#<?=$x['oid']?></td><td><?=e($x['name'])?> × <?=$x['qty']?><br><small class="muted"><?=e($x['buyer'])?> · <?=e($x['address'])?></small></td><td><?=money($x['qty']*$x['price'])?></td><td><form method="post"><input type="hidden" name="t" value="<?=csrf()?>"><input type="hidden" name="item" value="<?=$x['id']?>"><select name="status" onchange="this.form.submit()"><?php foreach(['pendiente','enviado','entregado'] as $s)echo '<option '.($x['status']===$s?'selected':'').'>'.$s.'</option>';?></select></form></td></tr><?php endforeach;?></table>
<?php }else{?><form method="post" class="card narrow"><input type="hidden" name="t" value="<?=csrf()?>"><h3>Configura tu tienda</h3><label>Nombre de la tienda<input name="name" value="<?=e($st['name'])?>" required></label><label>Región<select name="region"><?php foreach(REGIONES as $r)echo '<option '.($st['region']===$r?'selected':'').'>'.$r.'</option>';?></select></label><label>Historia de tu taller<textarea name="description"><?=e($st['description'])?></textarea></label><button name="store" class="btn">Guardar tienda</button></form><?php }
include 'app/Views/layout/footer.php';?>
